      fossilfaith: { co2: ['*', 1.3], co2total: ['*', 1.3], pm25: ['*', 1.25], airdeath: ['*', 1.2], fuelprice: ['*', 0.5], coal: ['+', 8], renew: ['+', -8], articles: ['*', 0.85], govspend: ['+', 2], disasters: ['+', 2], researchers: ['*', 0.9] },
